import json, collections
def objs(g):
    g=[r[:] for r in g]; bg=collections.Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]!=bg and (i,j) not in seen:
                stack=[(i,j)]; cells=[]
                while stack:
                    a,b=stack.pop()
                    if(a,b) in seen: continue
                    seen.add((a,b)); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        ca,cb=a+da,b+db
                        if 0<=ca<len(g) and 0<=cb<len(g[0]) and g[ca][cb]!=bg and (ca,cb) not in seen:
                            stack.append((ca,cb))
                out.append(cells)
    return out
