import os,re,collections,json,itertools
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)];cells=set([(i,j)])
                while st:
                    a,b=st.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        ca,cb=a+da,b+db
                        if 0<=ca<H and 0<=cb<W and g[ca][cb]!=bg and (ca,cb) not in cells:
                            st.append((ca,cb));cells.add((ca,cb))
                out.append(sorted(cells));seen|=cells
    return out

def exact_cover(k):
    inp=G[f'Demo pair {k} input']; op=G[f'Demo pair {k} output']
    cnt=collections.Counter(c for r in inp for c in r); bg=cnt.most_common(1)[0][0]
    ci=comps(inp,bg); oh,ow=len(op),len(op[0])
    omask={(a,b) for a in range(oh) for b in range(ow) if op[a][b]!=bg}
    templ=[]
    for p in ci:
        mr=min(a for a_,b_ in p); mc=min(b for a_,b_ in p)
        offs=sorted((a-mr,b-mc) for a,b in sorted(p))
        cmap={o:inp[mr+o[0]][mc+o[1]] for o in offs}
        templ.append((offs,cmap))
    def rec(idx,used,assign):
        if len(used)==len(omask):
            yield assign.copy(); return
        if idx>=len(templ): return
        offs,cmap=templ[idx]
        h=max(o[0] for o in offs)+1; w=max(o[1] for o in offs)+1
        for ra in range(oh-h+1):
            for rb in range(ow-w+1):
                cs=set((ra+r[0],rb+r[1]) for r in offs)
                if cs<=omask and not cs&used:
                    assign.append(((idx,ra,rb),cmap))
                    yield from rec(idx+1,used|cs,assign)
                    assign.pop()
    sols=list(rec(0,set(),[]))
    return templ,sols

for k in [2,3,4]:
    templ,sols=exact_cover(k)
    print('demo',k,'solutions',len(sols),'pieces',len(templ))
